import{_ as d,o as e,c as r,aw as o}from"./chunks/framework.DLufY-ao.js";const u=JSON.parse('{"title":"HTTP Headers","description":"","frontmatter":{},"headers":[],"relativePath":"wiki/dev-commit/network/http/http/3-http-headers.md","filePath":"wiki/dev-commit/network/http/http/3-http-headers.md"}'),a={name:"wiki/dev-commit/network/http/http/3-http-headers.md"};function c(s,t,h,i,n,l){return e(),r("div",null,[...t[0]||(t[0]=[o('<h1 id="http-headers" tabindex="-1">HTTP Headers <a class="header-anchor" href="#http-headers" aria-label="Permalink to &quot;HTTP Headers&quot;">​</a></h1><div class="tip custom-block"><p class="custom-block-title">Заголовки HTTP</p><ul><li><strong>Заголовки HTTP</strong> - строки в HTTP-сообщении, содержащие разделённую двоеточием пару параметр-значение</li></ul></div><h2 id="заголовки-http" tabindex="-1">Заголовки HTTP <a class="header-anchor" href="#заголовки-http" aria-label="Permalink to &quot;Заголовки HTTP&quot;">​</a></h2><ol><li><strong>General Headers</strong> («Основные заголовки») - основные заголовки для запросов клиента и ответов сервера</li><li><strong>Request Headers</strong> («Заголовки запроса») - используются только в запросах клиента</li><li><strong>Response Headers</strong> («Заголовки ответа») - только для ответов от сервера</li><li><strong>Entity Headers</strong> («Заголовки сущности») - заголовки, сопровождающие каждую сущность как в запросах клиента, так и в ответах сервера</li></ol><h3 id="_1-general-headers" tabindex="-1">1. General Headers <a class="header-anchor" href="#_1-general-headers" aria-label="Permalink to &quot;1. General Headers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Параметр</th><th>Значение</th><th>Пояснение</th></tr></thead><tbody><tr><td>Request URL</td><td><code>https://api.project.com/api/user</code></td><td></td></tr><tr><td>Request Method</td><td><code>POST</code></td><td></td></tr><tr><td>Status Code</td><td><code>200 OK</code></td><td></td></tr><tr><td>Remote Address</td><td><code>107.22.174.243:443</code></td><td></td></tr><tr><td>Referrer Policy</td><td><code>strict-origin-when-cross-origin</code></td><td>Определяет, сколько информации о referrer (отправляемой с заголовком Referer) должно быть включено в запросы</td></tr></tbody></table><h3 id="_2-request-headers" tabindex="-1">2. Request Headers <a class="header-anchor" href="#_2-request-headers" aria-label="Permalink to &quot;2. Request Headers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Заголовок</th><th>Пример значения</th><th>Пояснение</th></tr></thead><tbody><tr><td>Accept</td><td><code>text/plain</code></td><td>Список допустимых форматов ресурса</td></tr><tr><td>Accept-Encoding</td><td><code>&lt;compress|gzip|deflate|sdch|identity&gt;</code></td><td>Перечень поддерживаемых способов кодирования содержимого сущности при передаче</td></tr><tr><td>Accept-Language</td><td><code>ru,en</code></td><td>Список поддерживаемых естественных языков</td></tr><tr><td>Authorization</td><td><code>Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ==</code></td><td>Данные для авторизации</td></tr><tr><td>Connection</td><td><code>close|keep-alive</code></td><td>Сведения о проведении соединения</td></tr><tr><td>Host</td><td><code>api.project.com</code></td><td>Доменное имя и порт хоста запрашиваемого ресурса. Необходимо для поддержки виртуального хостинга на серверах</td></tr><tr><td>Origin</td><td><code>http://localhost:3000</code></td><td></td></tr><tr><td>Referer</td><td><code>http://localhost:3000/</code></td><td>Полный или относительный URI ресурса, с которого клиент сделал текущий запрос</td></tr><tr><td>User-Agent</td><td><code>Mozilla/5.0 (X11; Linux i686; rv:2.0.1) Gecko/20100101 Firefox/4.0.1</code></td><td>Список названий и версий клиента и его компонентов с комментариями</td></tr><tr><td>Accept-Charset</td><td><code>utf-8</code></td><td>Перечень поддерживаемых кодировок для предоставления пользователю</td></tr><tr><td>Proxy-Authorization</td><td><code>Basic QWxhZGRpbjpvcGVuIHNlc2FtZQ==</code></td><td>Информация для авторизации на прокси-сервере</td></tr></tbody></table><h3 id="_3-response-headers" tabindex="-1">3. Response Headers <a class="header-anchor" href="#_3-response-headers" aria-label="Permalink to &quot;3. Response Headers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Заголовок</th><th>Пример значения</th><th>Пояснение</th></tr></thead><tbody><tr><td>Allow</td><td><code>OPTIONS, GET, HEAD</code></td><td>Список поддерживаемых методов</td></tr><tr><td>Cache-Control</td><td><code>no-cache</code> …</td><td>Директивы для управления кэшированием</td></tr><tr><td>Connection</td><td><code>close|keep-alive</code></td><td>Сведения о проведении соединения</td></tr><tr><td>Content-Length</td><td><code>1348</code></td><td>Размер содержимого сущности в октетах (байтах)</td></tr><tr><td>Content-Type</td><td><code>text/html;charset=utf-8</code></td><td>Формат и способ представления сущности</td></tr><tr><td>Date</td><td><code>Tue, 15 Nov 1994 08:12:31 GMT</code></td><td>Дата генерации отклика</td></tr><tr><td>Location</td><td><code>http://example.com/about</code></td><td>URI, по которому клиенту следует перейти, или URI созданного ресурса</td></tr><tr><td>Server</td><td><code>Apache/2.2.17 (Win32) PHP/5.3.5</code></td><td>Список названий и версий веб-сервера и его компонентов с комментариями</td></tr></tbody></table><h3 id="_4-entity-headers" tabindex="-1">4. Entity Headers <a class="header-anchor" href="#_4-entity-headers" aria-label="Permalink to &quot;4. Entity Headers&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Заголовок</th><th>Пример значения</th><th>Пояснение</th></tr></thead><tbody><tr><td>Content-Language</td><td><code>en, ru</code></td><td>Один или несколько естественных языков содержимого сущности</td></tr><tr><td>Expires</td><td><code>Tue, 31 Jan 2012 15:02:53 GMT</code></td><td>Дата предполагаемого истечения срока актуальности сущности</td></tr><tr><td>Title</td><td>-</td><td>Заголовок сущности</td></tr></tbody></table>',12)])])}const b=d(a,[["render",c]]);export{u as __pageData,b as default};
